package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.core.*; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.deser.std.StdDeserializer; import com.gerenciadorrural.modules.herd.domain.*; import java.io.*; import java.time.*; import java.util.*;
public final class ReproductionRequestDeserializers {private ReproductionRequestDeserializers(){}private static JsonNode body(JsonParser p,Set<String> f)throws IOException{p.enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION.mappedFeature());JsonNode n=p.getCodec().readTree(p);if(!n.isObject())throw JsonMappingException.from(p,"O comando deve ser um objeto JSON");for(Iterator<String> i=n.fieldNames();i.hasNext();)if(!f.contains(i.next()))throw JsonMappingException.from(p,"A propriedade enviada não é permitida");return n;}private static UUID uuid(JsonNode n){if(n==null||n.isNull()||!n.isTextual())throw new IllegalArgumentException();return UUID.fromString(n.textValue());}private static Long number(JsonNode n,boolean r){if(n==null||n.isNull()){if(r)throw new IllegalArgumentException();return null;}if(!n.isIntegralNumber()||!n.canConvertToLong())throw new IllegalArgumentException();return n.longValue();}private static LocalDate date(JsonNode n,boolean r){if(n==null||n.isNull()){if(r)throw new IllegalArgumentException();return null;}if(!n.isTextual())throw new IllegalArgumentException();return LocalDate.parse(n.textValue());}private static String text(JsonNode n){if(n==null||n.isNull())return null;if(!n.isTextual())throw new IllegalArgumentException();return n.textValue();}private static <T>T fail(JsonParser p,Exception e)throws JsonMappingException{throw JsonMappingException.from(p,"O comando de reprodução é inválido",e);}public static final class Breeding extends StdDeserializer<HerdReproductionController.BreedingRequest>{public Breeding(){super(HerdReproductionController.BreedingRequest.class);}public HerdReproductionController.BreedingRequest deserialize(JsonParser p,DeserializationContext c)throws IOException{try{JsonNode n=body(p,Set.of("operationId","expectedVersion","serviceType","serviceOn","sireReference","expectedCalvingOn","notes"));return new HerdReproductionController.BreedingRequest(uuid(n.get("operationId")),number(n.get("expectedVersion"),true),ReproductionServiceType.valueOf(text(n.get("serviceType"))),date(n.get("serviceOn"),true),text(n.get("sireReference")),date(n.get("expectedCalvingOn"),false),text(n.get("notes")));}catch(Exception e){return fail(p,e);}}}public static final class Confirmation extends StdDeserializer<HerdReproductionController.TransitionRequest>{public Confirmation(){super(HerdReproductionController.TransitionRequest.class);}public HerdReproductionController.TransitionRequest deserialize(JsonParser p,DeserializationContext c)throws IOException{try{JsonNode n=body(p,Set.of("operationId","expectedVersion","occurredOn"));return new HerdReproductionController.TransitionRequest(uuid(n.get("operationId")),number(n.get("expectedVersion"),true),date(n.get("occurredOn"),true));}catch(Exception e){return fail(p,e);}}}public static final class Termination extends StdDeserializer<HerdReproductionController.TerminationRequest>{public Termination(){super(HerdReproductionController.TerminationRequest.class);}public HerdReproductionController.TerminationRequest deserialize(JsonParser p,DeserializationContext c)throws IOException{try{JsonNode n=body(p,Set.of("operationId","expectedVersion","endedOn","reason"));return new HerdReproductionController.TerminationRequest(uuid(n.get("operationId")),number(n.get("expectedVersion"),true),date(n.get("endedOn"),true),PregnancyTerminationReason.valueOf(text(n.get("reason"))));}catch(Exception e){return fail(p,e);}}}public static final class Calving extends StdDeserializer<HerdReproductionController.CalvingRequest>{public Calving(){super(HerdReproductionController.CalvingRequest.class);}public HerdReproductionController.CalvingRequest deserialize(JsonParser p,DeserializationContext c)throws IOException{try{JsonNode n=body(p,Set.of("operationId","expectedVersion","pregnancyId","expectedPregnancyVersion","calvedOn","calfId","identification","name","sex","birthDate"));return new HerdReproductionController.CalvingRequest(uuid(n.get("operationId")),number(n.get("expectedVersion"),true),n.hasNonNull("pregnancyId")?uuid(n.get("pregnancyId")):null,number(n.get("expectedPregnancyVersion"),false),date(n.get("calvedOn"),true),uuid(n.get("calfId")),text(n.get("identification")),text(n.get("name")),HerdAnimalSex.valueOf(text(n.get("sex"))),date(n.get("birthDate"),false));}catch(Exception e){return fail(p,e);}}}}
